#include <iostream>

int main() {
    bool found = false;
    int best = 0;
    int count = 0;
    int x;
    while (std::cin >> x) {
        count++;
        if (!found || x > best) {
            best = x;
            found = true;
        }
    }
    if (found) {
        std::cout << count << ' ' << best << '\n';
    } else {
        std::cout << "пусто\n";
    }
    return 0;
}

