#include <cstdlib>
#include <iostream>

int main() {
    int n;
    if (!(std::cin >> n) || n < 1) {
        return 0;
    }
    int *values = malloc(n * sizeof *values);
    for (int i = 0; i < n; i++) {
        std::cin >> values[i];
    }
    for (int i = n - 1; i >= 0; i--) {
        std::cout << values[i] << (i > 0 ? ' ' : '\n');
    }
    free(values);
    return 0;
}

